import{_ as a,o as n,c as p,aj as l}from"./chunks/framework.BdtAaXf2.js";const e="/assets/image-20240724165146560.DDUdHX97.png",t="/assets/image-20240724165725058.CnWP2mDQ.png",h="/assets/image-20240724165809469.FanrKKwT.png",k="/assets/image-20240724170053521.CqB8uNZ0.png",r="/assets/image-20240724172446641.C3TWRK-_.png",E="/assets/image-20240724172808954.YzvuTVBn.png",d="/assets/image-20240724172944978.DTUQfj7V.png",g="/assets/image-20240724171823959.CVKIwwl0.png",c="/assets/image-20240725131919196.CFtK2K77.png",y="/assets/image-20240725131740491.CL7AG9_i.png",o="/assets/image-20240725151553224.BxMhccjn.png",u="/assets/image-20240725162815736.VqXGLk2g.png",i="/assets/image-20240725163103371.CYfbX-lc.png",b="/assets/image-20240725180612568.DCPHtMLg.png",m="/assets/image-20240725181308829.B4GaJp1C.png",F="/assets/image-20240725181410268.851cC2Rd.png",C="/assets/image-20240726171415420.h7at7Py4.png",A="/assets/image-20240728155427829.3woPl9sC.png",B="/assets/image-20240728154002013.BUPeiElW.png",q="/assets/image-20240728162125926.CGKABE7S.png",M=JSON.parse('{"title":"手把手带你实现 鸿蒙应用-键盘音乐","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/手把手带你实现鸿蒙应用-键盘音乐/手把手带你实现鸿蒙应用-键盘音乐.md","filePath":"鸿蒙开发技巧/手把手带你实现鸿蒙应用-键盘音乐/手把手带你实现鸿蒙应用-键盘音乐.md","lastUpdated":1730788610000,"__rawMarkdown":"# 手把手带你实现 鸿蒙应用-键盘音乐\\n\\n## 先看结果\\n\\n![image-20240724165146560](readme.assets/image-20240724165146560.png)\\n\\n## 关键技术\\n\\n1. 基本布局技巧\\n2. AVPlayer\\n3. 面向对象 \\n4. 全部采用 V2版本 状态管理技术\\n\\n\\n\\n## 新建一个项目\\n\\n1. 创建项目\\n\\n   ![image-20240724165725058](readme.assets/image-20240724165725058.png)\\n\\n2. 新建项目\\n\\n   ![image-20240724165809469](readme.assets/image-20240724165809469.png)\\n\\n3. 目录结构 - 可以后期用到再去新建\\n\\n   ![image-20240724170053521](readme.assets/image-20240724170053521.png)\\n\\n\\n\\n\\n\\n## 设置全局沉浸式\\n\\n设置和不设置全局沉浸式的区别是这样的\\n\\n![image-20240724172446641](readme.assets/image-20240724172446641.png)\\n\\n\\n\\n1. 在 `src/main/ets/entryability/EntryAbility.ets` 文件内进行编辑\\n\\n2.  `loadContent` 中进行设置\\n\\n   ![image-20240724172808954](readme.assets/image-20240724172808954.png)\\n\\n   ```typescript\\n     //   1 设置应用全屏\\n     let windowClass: window.Window = windowStage.getMainWindowSync(); // 获取应用主窗口\\n   \\n     // 2   设置沉浸式\\n     windowClass.setWindowLayoutFullScreen(true)\\n   ```\\n\\n3. 此时效果是这样的 ， 文字也会直接在**状态栏**上显示\\n\\n   ![image-20240724172944978](readme.assets/image-20240724172944978.png)\\n\\n   4. 此时，考虑到不同设备的状态栏高度可能不同，所以我们需要\\n\\n      1. 动态获取状态栏高度，存到全局状态中 `AppStorageV2`\\n      2. 页面读取全局状态中的状态栏高度，单独给页面进行设置\\n\\n      ```typescript\\n         //   1 获取应用窗口对象\\n        const windowClass: window.Window = windowStage.getMainWindowSync(); // 获取应用主窗口\\n        //  2  设置全屏\\n        windowClass.setWindowLayoutFullScreen(true)\\n        // 3 获取布局避让遮挡的区域\\n        const type = window.AvoidAreaType.TYPE_NAVIGATION_INDICATOR;\\n      \\n      \\n        const avoidArea = windowClass.getWindowAvoidArea(type);\\n        const bottomRectHeight = avoidArea.bottomRect.height; // 获取到导航条区域的高度\\n        const vpHeight = px2vp(bottomRectHeight) //  转换成 vp单位的数值\\n        //   4 把导航栏高度数据 存在全局\\n        const appStatu = AppStorageV2.connect(AppStatu, \\"AppStatu\\", () => new AppStatu())\\n        appStatu!.vpHeight = vpHeight\\n      ```\\n\\n   5. `AppStatu` 是自定义类，用来存储数据 状态栏高度数据的\\n\\n      > src/main/ets/types/index.ets\\n\\n      ```typescript\\n      @ObservedV2\\n      export class AppStatu {\\n        @Trace vpHeight: number =0\\n      }\\n      ```\\n\\n      \\n\\n   \\n\\n## 搭建背景\\n\\n![image-20240724171823959](readme.assets/image-20240724171823959.png)\\n\\n```\\n  build() {\\n\\n    Column({ space: 30 }) {\\n\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .backgroundImage($r(\\"app.media.startIcon\\"))\\n    .backgroundImageSize(ImageSize.FILL)\\n    .backdropBlur(1000) // 对背景进行模糊\\n\\n  }\\n```\\n\\n\\n\\n## 搭建琴谱\\n\\n![image-20240725131919196](readme.assets/image-20240725131919196.png)\\n\\n### 琴谱背景区域\\n\\n使用背景图片+模糊搭建琴谱区域，高度由内容撑开\\n\\n![image-20240725131740491](readme.assets/image-20240725131740491.png)\\n\\n```typescript\\n  @Builder\\n  MusicScore() {\\n    // 琴谱\\n    Column({ space: 3 }) {\\n      Text(\\"琴谱\\")\\n    }\\n    .width(\\"100%\\")\\n    .backgroundImage($r(\\"app.media.startIcon\\"))\\n    .backgroundImageSize(ImageSize.FILL)\\n    .backdropBlur(500) // 对背景进行模糊\\n    .padding({\\n      top: this.appStatu!.vpHeight + 20\\n    })\\n  }\\n\\n  build() {\\n\\n    Column({ space: 30 }) {\\n      //   1 琴谱\\n      this.MusicScore()\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n\\n    .backgroundImage($r(\\"app.media.startIcon\\"))\\n    .backgroundImageSize(ImageSize.FILL)\\n    .backdropBlur(1000) // 对背景进行模糊\\n\\n  }\\n```\\n\\n### 定义琴谱数据类型\\n\\n琴谱只需要两个字段\\n\\n1. 琴谱对应歌曲的标题 `title`\\n2. 琴谱 对应的英文字母  `content`\\n\\n> src/main/ets/types/index.ets\\n\\n```typescript\\n@ObservedV2\\nexport class Lyric {\\n  @Trace title: string = \\"\\"\\n  @Trace content: string[] = []\\n}\\n```\\n\\n### 定义字母的正确和不正确的状态类型\\n\\n1. 如图所示，绿色为正确\\n2. 黄色为未输入或者不正确\\n\\n![image-20240725151553224](readme.assets/image-20240725151553224.png)\\n\\n```typescript\\n@ObservedV2\\nexport class LyricStatu {\\n  @Trace title: string = \\"\\"\\n  @Trace isCorrect: boolean = false\\n}\\n```\\n\\n### 处理要渲染的数据\\n\\n为了方便页面的效果处理，我们需要将手上的数据，简单处理下，方便页面渲染\\n\\n1. 手上的数据 \\n\\n   > src/main/ets/mock/index.ets\\n\\n   ```typescript\\n   import { Lyric } from \'../types\'\\n   \\n   export const tonghua: Lyric = {\\n     title: \\"童话\\",\\n     content: [\\"LONOL\\", \\"LONOL\\", \\"OOMML\\", \\"LONOL\\", \\"LQPPO\\", \\"LONOM\\", \\"MMOTS\\", \\"PPRRQQ\\", \\"QQNPOONO\\", \\"ONOR\\", \\"LSRQPPPRRQQ\\",\\n       \\"QQVUTUV\\", \\"VPOT\\", \\"TTSSSLSRQQRQ\\", \\"QRQ\\", \\"RQPOOQST\\", \\"TTSPPRQ\\", \\"OQST\\", \\"TTSPPRQRQPO\\", \\"PQMMOONO\\",]\\n   }\\n   ```\\n\\n   \\n\\n2. 处理后的数据结构\\n\\n   ![image-20240725162815736](readme.assets/image-20240725162815736.png)\\n\\n3. 为什么要这样处理，因为让它方便渲染\\n\\n   ![image-20240725163103371](readme.assets/image-20240725163103371.png)\\n\\n4. 如何处理呢 在页面打开的时候在`aboutToAppear`中处理即可 `lyricList`\\n\\n   ```typescript\\n   import { tonghua } from \'../mock\'\\n   import {   LyricStatu } from \'../types\'\\n   @Entry\\n   @ComponentV2\\n   struct Index {\\n     // 琴谱列表\\n    @Local lyricList: LyricStatu[][] = []\\n     aboutToAppear() {\\n       this.lyricList = tonghua.content.map(row => {\\n         const list = row.split(\'\').map(v => {\\n           const o = new LyricStatu()\\n           o.title = v\\n           return o\\n         })\\n         return list\\n       })\\n     }\\n   }\\n   ```\\n```\\n   \\n### 渲染琴谱\\n   \\n   ```typescript\\n   // 状态栏的高度\\n   @Local appStatu: AppStatu | undefined = AppStorageV2.connect(AppStatu, \\"AppStatu\\", () => new AppStatu())\\n   \\n   @Builder\\n     MusicScore() {\\n       // 琴谱\\n       Column({ space: 3 }) {\\n         //   标题\\n         Text(tonghua.title)\\n           .fontSize(30)\\n           .fontColor(\\"#fff\\")\\n         ForEach(this.lyricList, (item1: LyricStatu[]) => {\\n           Row({ space: 5 }) {\\n             ForEach(item1, (item2: LyricStatu) => {\\n               Text(item2.title)\\n                 .fontColor(item2.isCorrect ? \\"#23d96e\\" : \\"#ffcf49\\")\\n                 .fontSize(20)\\n             })\\n           }\\n         })\\n       }\\n       .width(\\"100%\\")\\n       .backgroundImage($r(\\"app.media.startIcon\\"))\\n       .backgroundImageSize(ImageSize.FILL)\\n       .backdropBlur(500) // 对背景进行模糊\\n       .padding({ // 设置文字下移，否则被屏幕摄像头给挡住\\n         top: this.appStatu!.vpHeight + 20\\n       })\\n     }\\n   \\n   \\n   \\n     build() {\\n   \\n       Column({ space: 30 }) {\\n         //   1 琴谱\\n         this.MusicScore()\\n   \\n         // this.KeyBoard()\\n       }\\n       .width(\\"100%\\")\\n       .height(\\"100%\\")\\n   \\n       .backgroundImage($r(\\"app.media.startIcon\\"))\\n       .backgroundImageSize(ImageSize.FILL)\\n       .backdropBlur(1000) // 对背景进行模糊\\n   \\n     }\\n   \\n\\n```\\n\\n   得到结果\\n\\n   ![image-20240725180612568](readme.assets/image-20240725180612568.png)\\n\\n## 搭建键盘\\n\\n![image-20240725181308829](readme.assets/image-20240725181308829.png)\\n\\n### 准备音频资源\\n\\n键盘一个26个字母，对应边有26个声音。一一相对应\\n\\n其中，我们的静态资源存放在 rawFile中，鸿蒙应用在打包时不会对里面的文件做任何的编译处理，然后在使用的时候需要搭配AVPlayer使用。如\\n\\n```typescript\\n const res = await getContext().resourceManager.getRawFd(\\"paino1.mp3\\")\\nAVPlayer实例.fdSrc = res\\n```\\n\\n\\n\\n![image-20240725181410268](readme.assets/image-20240725181410268.png)\\n\\n### 定义字母和音频映射数据\\n\\n> src/main/ets/mock/index.ets\\n\\n```typescript\\nexport const letters: LettemMusic[][] = [\\n  [\\n    { name: \\"Q\\", src: \\"paino17.mp3\\" },\\n    { name: \\"W\\", src: \\"paino23.mp3\\" },\\n    { name: \\"E\\", src: \\"paino5.mp3\\" },\\n    { name: \\"R\\", src: \\"paino18.mp3\\" },\\n    { name: \\"T\\", src: \\"paino20.mp3\\" },\\n    { name: \\"Y\\", src: \\"paino25.mp3\\" },\\n    { name: \\"U\\", src: \\"paino21.mp3\\" },\\n    { name: \\"I\\", src: \\"paino9.mp3\\" },\\n    { name: \\"O\\", src: \\"paino15.mp3\\" },\\n    { name: \\"P\\", src: \\"paino16.mp3\\" },\\n  ],\\n  [\\n    { name: \\"A\\", src: \\"paino1.mp3\\" },\\n    { name: \\"S\\", src: \\"paino19.mp3\\" },\\n    { name: \\"D\\", src: \\"paino4.mp3\\" },\\n    { name: \\"F\\", src: \\"paino6.mp3\\" },\\n    { name: \\"G\\", src: \\"paino7.mp3\\" },\\n    { name: \\"H\\", src: \\"paino8.mp3\\" },\\n    { name: \\"J\\", src: \\"paino10.mp3\\" },\\n    { name: \\"K\\", src: \\"paino11.mp3\\" },\\n    { name: \\"L\\", src: \\"paino12.mp3\\" },\\n  ],\\n  [\\n    { name: \\"Z\\", src: \\"paino26.mp3\\" },\\n    { name: \\"X\\", src: \\"paino24.mp3\\" },\\n    { name: \\"C\\", src: \\"paino3.mp3\\" },\\n    { name: \\"V\\", src: \\"paino22.mp3\\" },\\n    { name: \\"B\\", src: \\"paino2.mp3\\" },\\n    { name: \\"N\\", src: \\"paino14.mp3\\" },\\n    { name: \\"M\\", src: \\"paino13.mp3\\" },\\n  ]\\n]\\n```\\n\\n### 页面关联数据\\n\\n```typescript\\nimport { letters, tonghua } from \'../mock\'\\n\\n...\\n// 键盘 和 对应的音乐按键\\n@Local letters: LettemMusic[][] = letters\\n```\\n\\n### 构建键盘布局结构\\n\\n```typescript\\n  // 键盘\\n  @Builder\\n  KeyBoard() {\\n    Column({ space: 10 }) {\\n      ForEach(this.letters, (items: LettemMusic[]) => {\\n        Row({ space: 8 }) {\\n          ForEach(items, (item: LettemMusic) => {\\n            Text(item.name)\\n              .backgroundColor(\\"rgba(255,255,255,0.9)\\")\\n              .padding(10)\\n              .borderRadius(10)\\n              .fontWeight(400)\\n              .stateStyles({\\n                clicked: {\\n                  .backgroundColor(\\"#fff\\")\\n                }\\n              })\\n          })\\n        }\\n        .width(\\"100%\\")\\n        .padding(2)\\n        .justifyContent(FlexAlign.Center)\\n      })\\n\\n    }\\n    .layoutWeight(1)\\n  }\\n\\n```\\n\\n### 使用键盘布局结构\\n\\n```typescript\\n  build() {\\n\\n    Column({ space: 30 }) {\\n      //   1 琴谱\\n      this.MusicScore()\\n\\n      //   2 键盘\\n      this.KeyBoard()\\n    }\\n    .width(\\"100%\\")\\n    .height(\\"100%\\")\\n    .backgroundImage($r(\\"app.media.startIcon\\"))\\n    .backgroundImageSize(ImageSize.FILL)\\n    .backdropBlur(1000) // 对背景进行模糊\\n\\n  }\\n```\\n\\n## 按下键盘，播放音乐功能\\n\\n### 关键流程\\n\\n1. 封装AVPlayer管理类，每一个按键对应一个单独声音，因为上一个声音没有播放完毕，我们是可以同时播放第二个、第三个声音的，所以可以通过实例化多个 AVPlayer来使其一一对应\\n2. 点击键盘 获取键盘对应的音乐路径\\n3. 将音乐路径传递给AVPlayer，使其播放声音\\n\\n### 了解AVPlayer\\n\\n> 使用AVPlayer可以实现端到端播放原始媒体资源，本开发指导将以完整地播放一首音乐作为示例，向开发者讲解AVPlayer音频播放相关功能。\\n>\\n> 播放的全流程包含：创建AVPlayer，设置播放资源，设置播放参数（音量/倍速/焦点模式），播放控制（播放/暂停/跳转/停止），重置，销毁资源。\\n>\\n> 在进行应用开发的过程中，开发者可以通过AVPlayer的state属性主动获取当前状态或使用on(\'stateChange\')方法监听状态变化。如果应用在音频播放器处于错误状态时执行操作，系统可能会抛出异常或生成其他未定义的行为。\\n\\n使用流程基本围绕这一张图即可 \\n\\n![image-20240726171415420](readme.assets/image-20240726171415420.png)\\n\\n\\n\\n### AVPlayer基本使用流程\\n\\n1. 创建 AVPlayer 实例  *此时，avPlayer进入空闲状态 idle*\\n\\n   ```typescript\\n   const avPlayer = await media.createAVPlayer()\\n   ```\\n\\n2. 监听状态的改变 我们对播放器的每一个操作，都会影响到它状态发生改变\\n\\n   ```typescript\\n   avPlayer.on(\\"stateChange\\", (state) => {\\n         switch (state) {\\n           // 如果播放器初始化完毕，那么就让它开始状态\\n           case \\"initialized\\":\\n             avPlayer.prepare()\\n             break;\\n           case \\"prepared\\":\\n            // 如果播放器准备完毕，就让它变成开始播放     \\n             avPlayer.play()\\n             break;\\n           default:\\n             break;\\n         }\\n       })\\n   ```\\n\\n3. 设置播放音乐的URL\\n\\n   ```typescript\\n   \\tconst res = await getContext().resourceManager.getRawFd(this.url)\\n       avPlayer.fdSrc = res  // 设置完播放器后，播放器会进入 initialized 状态\\n   ```\\n\\n4. 开始播放\\n\\n   我们已经在  `prepared` 状态中，设置了自动播放了 `avPlayer.play()`\\n\\n### 核心思路讲解\\n\\n1. 我们思考一下弹钢琴的逻辑，我们是不是可以同时按下多个按键，同时播放声音的？ 所以我们需要 new 多个  AVPlayer播放器实例\\n2. 如果你重复按下两个相同的琴键，**终止上一个琴键的播放，马上开启新的一个琴键的播放**\\n3. 最后，当这个琴键播放完毕时，我们要销毁掉这个实例，释放内存\\n\\n\\n\\n### AVPlayerManager \\n\\n> src/main/ets/utils/AvPlayerManager.ets\\n>\\n> 实现了对 AVPlayer功能的基本封装\\n\\n```typescript\\nimport { media } from \'@kit.MediaKit\'\\n\\nclass AVPlayerManager {\\n  // 播放器实例\\n  avPlayer: media.AVPlayer | null = null;\\n  url: string = \\"\\"\\n  // 播放完毕的回调事件\\n  playComplete: () => void = () => {\\n  }\\n\\n  // 构造函数\\n  constructor(url: string) {\\n    this.init()\\n    this.url = url\\n  }\\n\\n  // 初始化\\n  async init() {\\n    this.avPlayer = await media.createAVPlayer()\\n    this.avPlayer.on(\\"stateChange\\", (state) => {\\n      switch (state) {\\n        case \\"initialized\\":\\n          this.avPlayer?.prepare()\\n          break;\\n        case \\"prepared\\":\\n          this.avPlayer?.play()\\n          break;\\n        case \\"completed\\":\\n          // 播放完毕，销毁实例\\n          this.avPlayer?.release()\\n          this.playComplete()\\n          break;\\n        default:\\n          break;\\n      }\\n    })\\n    this.avPlayer.on(\\"error\\", (err) => {\\n      console.log(\\"err\\", err)\\n    })\\n    // 设置URL\\n    const res = await getContext().resourceManager.getRawFd(this.url)\\n    this.avPlayer!.fdSrc = res\\n  }\\n}\\n\\n\\nexport default AVPlayerManager\\n```\\n\\n\\n\\n### 对琴谱数据进行扁平化处理\\n\\n> 方便判断按下的键盘是否正确和播放正确的按键音乐\\n\\n![image-20240728155427829](readme.assets/image-20240728155427829.png)\\n\\n```typescript\\n// 用来判断按下的按键和琴谱是否对应的\\nletterFlat: LettemMusic[] = []\\n\\naboutToAppear() {\\n    this.letterFlat = this.letters.flat()\\n    // ...\\n  }\\n```\\n\\n\\n\\n### 给键盘添加点击事件\\n\\n```typescript\\n .onClick(() => this.playLetter(item))\\n```\\n\\n![image-20240728154002013](readme.assets/image-20240728154002013.png)\\n\\n### 实现点击播放音乐\\n\\n```typescript\\n  // 用来管理正在播放的声音对应的AVPlayer实例 如按下了 Q W ，那么就会出生两个 AVPlayer实例\\n  avPlayManagerList: AVPlayerManager[] = []\\n  \\n  // 点击键盘播放音乐\\n  playLetter(letter: LettemMusic) {\\n    // 根据点击的键盘 找到琴谱音乐对象 如 { name :\\"A\\" ,src :\\"paino1.mp1\\"}\\n    const item = this.letterFlat.find(v => v.name === letter.name)\\n\\n    // 根据播放的歌曲路径 判断当前音乐是否正在播放\\n    const avIndex = this.avPlayManagerList.findIndex(v => v.url === item!.src)\\n\\n    if (avIndex !== -1) {\\n      // 如果正在播放 马上销毁\\n      this.avPlayManagerList[avIndex].avPlayer?.release()\\n      // 并且从数组中移除\\n      this.avPlayManagerList.splice(avIndex, 1)\\n    }\\n    // 根据当前点击的键盘创建对应的AVPlayer实例\\n    const avplayManager = new AVPlayerManager(letter.src)\\n    // 追加到数组中\\n    this.avPlayManagerList.push(avplayManager)\\n\\n    // 添加一个播放完毕的回调，用来删除avPlayManagerList数组中的AvPlay\\n    avplayManager.playComplete = () => {\\n      const index = this.avPlayManagerList.findIndex(v => v.url === item!.src)\\n      this.avPlayManagerList.splice(index, 1)\\n    }\\n  }\\n  \\n```\\n\\n## 按下键盘，判断按键是否正确\\n\\n类似练习打字效果，按对按键了，就设置绿色，如：\\n\\n![image-20240728162125926](readme.assets/image-20240728162125926.png)\\n\\n因为我们的琴谱是个二维数组\\n\\n![image-20240725163103371](readme.assets/image-20240725163103371.png)\\n\\n因此，我们也是定义一个数组 [行的坐标，列的坐标]，分别是二维数组相对应\\n\\n```\\n  // 用户弹的到琴谱坐标\\n  nextRowColumn: number[] = [0, 0]\\n```\\n\\n接着，也是在点击事件中，根据按下的按键和对应的琴谱是否相等，如果是，设置绿色\\n\\n```typescript\\n  // 点击键盘播放音乐\\n  playLetter(letter: LettemMusic) {\\n\\n  // ....\\n    // 获取行坐标\\n    const row = this.nextRowColumn[0]\\n    // 获取列坐标\\n    const column = this.nextRowColumn[1]\\n    // 判断当前的坐标是否超出范围\\n    if (this.lyricList[row] && this.lyricList[row][column]) {\\n      // 获取坐标对应的琴谱\\n      const item = this.lyricList[row][column]\\n      // 判断按下的按键和对应的琴谱是否相等 如 L == L\\n      if (item.title === letter.name) {\\n        // 设置选中\\n        item.isCorrect = true\\n        // 以下代码是设置坐标递进\\n        if (this.lyricList[row][column+1]) {\\n          this.nextRowColumn[1] = column + 1\\n        } else if (this.lyricList[row+1]) {\\n          this.nextRowColumn[0] = row + 1\\n          this.nextRowColumn[1] = 0\\n        } else {\\n          console.log(\\"最后一个了\\")\\n        }\\n      }\\n    }\\n  }\\n```\\n\\n\\n\\n## 小结\\n\\n1. 本篇教程可能用词不够简洁，如按键、键盘、音乐、乐谱、琴谱有些名词其实是代表同一个意思。\\n2. 页面结构功能没有拆分成组件独立管理\\n3. 功能稍弱，如切换琴谱，按键反馈、登录、分享、排行功能都缺失，只实现了核心的功能"}'),v={name:"鸿蒙开发技巧/手把手带你实现鸿蒙应用-键盘音乐/手把手带你实现鸿蒙应用-键盘音乐.md"};function D(P,s,w,L,S,x){return n(),p("div",null,[...s[0]||(s[0]=[l("",88)])])}const V=a(v,[["render",D]]);export{M as __pageData,V as default};
